# This file was generated by the `rspec --init` command. Conventionally, all
# specs live under a `spec` directory, which RSpec adds to the `$LOAD_PATH`.
# The generated `.rspec` file contains `--require spec_helper` which will cause this
# file to always be loaded, without a need to explicitly require it in any files.
#
# Given that it is always loaded, you are encouraged to keep this file as
# light-weight as possible. Requiring heavyweight dependencies from this file
# will add to the boot time of your test suite on EVERY test run, even for an
# individual file that may not need all of that loaded. Instead, make a
# separate helper file that requires this one and then use it only in the specs
# that actually need it.
#
# The `.rspec` file also contains a few flags that are not defaults but that
# users commonly want.
#
# See http://rubydoc.info/gems/rspec-core/RSpec/Core/Configuration
require "simplecov"
SimpleCov.start do
  add_filter "/spec/"
end

require "webmock/rspec"
require "git_trend"

RSpec.configure do |config|
  config.expect_with :rspec do |expectations|
    expectations.syntax = :expect
  end

  config.mock_with :rspec do |mocks|
    mocks.syntax = :expect
    mocks.verify_partial_doubles = true
  end

  config.filter_run_when_matching :focus
  config.expose_dsl_globally = false

  # Emoji width depends on the terminal, so fix it to get stable results.
  config.before do
    allow(Unicode::DisplayWidth::EmojiSupport).to receive(:recommended).and_return(:all)
  end

  config.example_status_persistence_file_path = "spec/examples.txt"
  Kernel.srand config.seed
end

def load_http_stub(file_name)
  file_path = File.join(__dir__, "fixtures", file_name)
  file_path = File.join(file_path, "index") if File.directory? file_path
  File.read(file_path)
end

class String
  def unindent
    gsub(/^\s+\|/, "")
  end
end
